// quota.js — render status/quota.json into the fleet quota board.
// Zero-build: plain DOM, no fetch dependencies beyond the JSON file
// generated by src/quota_refresh.oo.
(function () {
  'use strict';

  var grid = document.getElementById('quota-grid');
  var stamp = document.getElementById('quota-stamp');
  var panesWrap = document.getElementById('quota-panes-wrap');
  if (!grid || !stamp) return;

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function row(label, value, cls) {
    var r = el('div', 'quota-row');
    r.appendChild(el('span', null, label));
    var v = el('b', cls || null, value);
    r.appendChild(v);
    return r;
  }

  function stateCls(s) {
    if (s === 'EXHAUSTED' || s === 'DOWN' || s === 'ERR') return 'quota-state-bad';
    if (s === 'OK' || s === 'UP' || s === 'LIVE') return 'quota-state-ok';
    return 'quota-state-warn';
  }

  function card(name, src, rows, ts) {
    var c = el('div', 'quota-card');
    c.appendChild(el('h3', null, name));
    c.appendChild(el('span', 'quota-src', src));
    rows.forEach(function (r) { c.appendChild(r); });
    if (ts) c.appendChild(el('div', 'quota-ts', ts));
    return c;
  }

  function failCard(name, src) {
    return card(name, src, [row('state', 'UNAVAILABLE', 'quota-state-bad'),
                            row('detail', 'source unreadable — "ok":false')], null);
  }

  function num(n) { return (typeof n === 'number') ? n.toLocaleString('en-US') : '—'; }

  function render(d) {
    stamp.textContent = 'generated_at ' + (d.generated_at || 'unknown') +
      ' (epoch ' + (d.generated_epoch || 0) + ')';
    var a = d.agents || {};

    if (a.mcode && a.mcode.ok) {
      grid.appendChild(card('mcode', a.mcode.source, [
        row('input tokens (5h)', num(a.mcode.in_5h)),
        row('output tokens (5h)', num(a.mcode.out_5h)),
        row('turns (5h)', num(a.mcode.turns_5h)),
        row('cost usd (24h)', '$' + (a.mcode.cost_usd_24h || 0)),
        row('remaining', 'subscription ledger — see agent /usage', 'quota-state-warn')
      ], 'latest turn ms=' + (a.mcode.latest_ms_5h || 0)));
    } else grid.appendChild(failCard('mcode', a.mcode && a.mcode.source));

    if (a.grok && a.grok.ok) {
      grid.appendChild(card('grok', a.grok.source, [
        row('sessions', num(a.grok.sessions)),
        row('sessions with usage', num(a.grok.with_usage)),
        row('total tokens', num(a.grok.total_tokens)),
        row('cost usd ticks', num(a.grok.cost_usd_ticks)),
        row('remaining', 'per-session sums — no plan-limit API', 'quota-state-warn')
      ], 'latest usage at ' + (a.grok.latest_at || 'n/a')));
    } else grid.appendChild(failCard('grok', a.grok && a.grok.source));

    if (a.devin && a.devin.ok) {
      grid.appendChild(card('devin', a.devin.source, [
        row('panes watched', num(a.devin.panes)),
        row('panes reporting', num(a.devin.reporting)),
        row('max context pressure', num(a.devin.max_ctx_pct) + '%',
            stateCls((a.devin.max_ctx_pct || 0) > 80 ? 'BAD' : 'OK')),
        row('remaining', 'context window headroom 100−pct', 'quota-state-ok')
      ], 'footer Context: (NN%) proxy per pane'));
    } else grid.appendChild(failCard('devin', a.devin && a.devin.source));

    if (a.vibe && a.vibe.ok) {
      grid.appendChild(card('vibe', a.vibe.source, [
        row('state', a.vibe.state || 'UNKNOWN', stateCls(a.vibe.state)),
        row('402 events seen', num(a.vibe.count_402)),
        row('spend', 'budget gate is binary — no meter', 'quota-state-warn'),
        row('remaining', a.vibe.state === 'EXHAUSTED' ? 'none (402s live)' : 'available',
            stateCls(a.vibe.state))
      ], 'last 402 at ' + (a.vibe.last_402_at || 'n/a')));
    } else grid.appendChild(failCard('vibe', a.vibe && a.vibe.source));

    var det = a.devin && a.devin.detail;
    if (det && det.length && panesWrap) {
      var tbl = el('table', 'quota-panes');
      var head = el('tr');
      ['pane', 'context %', 'state'].forEach(function (h) { head.appendChild(el('th', null, h)); });
      tbl.appendChild(head);
      det.forEach(function (p) {
        var tr = el('tr');
        tr.appendChild(el('td', null, p.pane));
        tr.appendChild(el('td', null, p.ctx_pct >= 0 ? p.ctx_pct + '%' : '—'));
        tr.appendChild(el('td', null,
          p.ctx_pct < 0 ? 'no footer' : p.ctx_pct > 80 ? 'high' : 'ok'));
        tbl.appendChild(tr);
      });
      panesWrap.textContent = '';
      panesWrap.appendChild(tbl);
    } else if (panesWrap) {
      panesWrap.innerHTML = '<p class="quota-note">No devin panes reporting.</p>';
    }
  }

  function renderTrend(lines) {
    var wrap = document.getElementById('quota-trend-wrap');
    if (!wrap) return;
    var rows = [];
    lines.forEach(function (ln) {
      var s = ln.trim();
      if (!s) return;
      try { rows.push(JSON.parse(s)); } catch (e) { /* skip malformed */ }
    });
    rows = rows.slice(-7);
    if (!rows.length) {
      wrap.innerHTML = '<p class="quota-note">No daily snapshots yet — history accumulates one line per refresh run (day-grain dedupe).</p>';
      return;
    }
    var tbl = el('table', 'quota-panes');
    var head = el('tr');
    ['date', 'at (UTC)', 'mcode out (5h)', 'mcode turns', 'grok tokens', 'grok ticks', 'devin rep/max', 'vibe'].forEach(function (h) {
      head.appendChild(el('th', null, h));
    });
    tbl.appendChild(head);
    rows.forEach(function (r) {
      var tr = el('tr');
      tr.appendChild(el('td', null, r.date || '?'));
      tr.appendChild(el('td', null, r.at || '?'));
      tr.appendChild(el('td', null, num(r.m_out)));
      tr.appendChild(el('td', null, num(r.m_turns)));
      tr.appendChild(el('td', null, num(r.g_tok)));
      tr.appendChild(el('td', null, num(r.g_ticks)));
      tr.appendChild(el('td', null, (r.d_rep || 0) + '/' + (r.d_pan || 0) + ' @ ' + (r.d_max >= 0 ? r.d_max + '%' : '—')));
      var vs = el('td', null, r.v || '?');
      if (r.v === 'EXHAUSTED') vs.className = 'quota-state-bad';
      else if (r.v === 'OK') vs.className = 'quota-state-ok';
      tr.appendChild(vs);
      tbl.appendChild(tr);
    });
    wrap.textContent = '';
    wrap.appendChild(tbl);
  }

  fetch('quota.json', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.json() : Promise.reject(r.status); })
    .then(render)
    .catch(function () {
      stamp.textContent = 'quota.json unavailable — run the .oo refresh driver (see below).';
      grid.appendChild(el('p', 'quota-note', 'No data file found. The board renders status/quota.json generated by src/quota_refresh.oo.'));
    });

  fetch('quota_history.jsonl', { cache: 'no-store' })
    .then(function (r) { return r.ok ? r.text() : Promise.reject(r.status); })
    .then(function (t) { renderTrend(t.split('\n')); })
    .catch(function () {
      var w = document.getElementById('quota-trend-wrap');
      if (w) w.innerHTML = '<p class="quota-note">quota_history.jsonl not published yet — first refresh creates it.</p>';
    });
})();
